"use client";

import { useState } from "react";
import { useRouter } from "next/navigation";

type Rule = { eventType: string; experienceAmount: number; coinAmount: number; dailyLimit: number | null; weeklyLimit: number | null; isActive: boolean };
export function RewardRulesEditor({ initial }: { initial: Rule[] }) { const router = useRouter(); const [rules, setRules] = useState(initial); const [message, setMessage] = useState<string | null>(null); async function save(rule: Rule) { setMessage(null); const response = await fetch(`/api/admin/rewards/${rule.eventType}`, { method: "PATCH", headers: { "Content-Type": "application/json" }, body: JSON.stringify(rule) }); setMessage(response.ok ? `${rule.eventType} saved.` : "Unable to save rule."); if (response.ok) router.refresh(); } return <section className="mt-7 overflow-x-auto rounded-2xl border bg-white p-5"><table className="min-w-full text-left text-sm"><thead><tr className="border-b"><th className="p-2">Event</th><th className="p-2">XP</th><th className="p-2">Coins</th><th className="p-2">Daily limit</th><th className="p-2">Active</th><th /></tr></thead><tbody>{rules.map((rule, index) => <tr key={rule.eventType} className="border-b"><td className="p-2 font-semibold">{rule.eventType}</td><td className="p-2"><input type="number" min="0" value={rule.experienceAmount} onChange={(event) => setRules(rules.map((item, itemIndex) => itemIndex === index ? { ...item, experienceAmount: Number(event.target.value) } : item))} className="w-20 rounded border px-2 py-1" /></td><td className="p-2"><input type="number" min="0" value={rule.coinAmount} onChange={(event) => setRules(rules.map((item, itemIndex) => itemIndex === index ? { ...item, coinAmount: Number(event.target.value) } : item))} className="w-20 rounded border px-2 py-1" /></td><td className="p-2"><input type="number" min="1" value={rule.dailyLimit ?? ""} onChange={(event) => setRules(rules.map((item, itemIndex) => itemIndex === index ? { ...item, dailyLimit: event.target.value ? Number(event.target.value) : null } : item))} className="w-20 rounded border px-2 py-1" /></td><td className="p-2"><input type="checkbox" checked={rule.isActive} onChange={(event) => setRules(rules.map((item, itemIndex) => itemIndex === index ? { ...item, isActive: event.target.checked } : item))} /></td><td className="p-2"><button onClick={() => void save(rule)} className="rounded bg-blue-700 px-3 py-1 font-semibold text-white">Save</button></td></tr>)}</tbody></table>{message ? <p role="status" className="mt-3 text-sm">{message}</p> : null}</section>; }
